        asra: { es: "Extraño artefacto procedente de un tiempo anterior a Hallownest. Contiene líquido volátil del Abismo.", en: "Rare artifact from a time before Hallownest. Volatile liquid of the Abyss writhes within." },
        radiant: { es: "Extraño artedacto procedente de un tiempo anterior a Hallownest, sus espiras gemelas adoptan una forma unificada. Contiene una gran cantidad de liquido del Abismo, perfectamente inmóvil.", en: "Rare artifact from a time before Hallownest, its spires twined in a unified form. Contains a large amount of liquid from the Abyss, perfectly still." },
